// ── Truth table generator ─────────────────────────────────────
function truthTable(vars, formula) {
  const n = vars.length;
  const rows = 1 << n; // 2^n
  console.log(vars.join('  ') + '  | Result');
  console.log('-'.repeat(vars.length * 4 + 10));
  for (let mask = 0; mask < rows; mask++) {
    const vals = {};
    vars.forEach((v, i) => {
      vals[v] = Boolean(mask & (1 << (n - 1 - i)));
    });
    const result = formula(vals);
    const row = vars.map(v => (vals[v] ? 'T' : 'F')).join('   ');
    console.log(row + '  | ' + (result ? 'T' : 'F'));
  }
}

// P → Q  ≡  ¬P ∨ Q
const implication = ({P, Q}) => !P || Q;
truthTable(['P', 'Q'], implication);
// P  Q  | Result
// T  T  | T
// T  F  | F   ← only false row: promise made and broken
// F  T  | T   ← vacuously true
// F  F  | T   ← vacuously true

console.log('---');

// De Morgan: ¬(P ∧ Q) ≡ ¬P ∨ ¬Q  — should always match
const left  = ({P, Q}) => !(P && Q);
const right = ({P, Q}) => !P || !Q;
const pairs = [[true,true],[true,false],[false,true],[false,false]];
const demorgan = pairs.every(([P, Q]) => left({P,Q}) === right({P,Q}));
console.log('De Morgan verified:', demorgan); // true

// ── Induction: prove sum of 0..n = n*(n+1)/2 ─────────────────
function sumDirect(n) {
  let s = 0;
  for (let i = 0; i <= n; i++) s += i;
  return s;
}
function sumFormula(n) { return n * (n + 1) / 2; }

// Verify for many n — the proof by induction guarantees this for all n
const inductionHolds = Array.from({length: 100}, (_, n) =>
  sumDirect(n) === sumFormula(n)
).every(Boolean);
console.log('Sum formula holds for n=0..99:', inductionHolds); // true

// ── Predicate logic: quantifiers ─────────────────────────────
// ∀x P(x)  → every element in domain satisfies P
// ∃x P(x)  → at least one element satisfies P

// Simulate ∀ and ∃ over a finite domain
const domain = [2, 3, 5, 7, 11, 13, 17, 19];
const isPrime = n => n < 2 ? false :
  Array.from({length: Math.floor(Math.sqrt(n)) - 1}, (_, i) => i + 2)
    .every(d => n % d !== 0);

// ∀x ∈ domain: isPrime(x)
const allPrime = domain.every(isPrime);
console.log('∀x isPrime(x):', allPrime); // true (domain chosen that way)

// ∃x ∈ {1..20}: x > 15
const d2 = Array.from({length: 20}, (_, i) => i + 1);
const existsGt15 = d2.some(x => x > 15);
console.log('∃x > 15:', existsGt15); // true

// Negation of quantifiers (De Morgan for quantifiers):
// ¬(∀x P(x)) ≡ ∃x ¬P(x)
// ¬(∃x P(x)) ≡ ∀x ¬P(x)

// Example: negate '∀x: x is even'
// Equivalent to '∃x: x is not even' — find one odd number to disprove
const someOdd = d2.some(x => x % 2 !== 0);
console.log('¬(∀x even) = ∃x odd:', someOdd); // true

